#### REQ-LENS-011-003: Automatic Schema Validation

**Status**: Mandatory (Phase 2)
**Rationale**: Prevent invalid messages from being displayed

**Validation Behavior**:
- When browsing topic: Automatically detect schema ID from message headers
- Fetch schema from Glue Schema Registry
- Validate message payload against schema
- Display validation errors in UI
- Support Avro, JSON Schema, Protobuf formats

**Implementation**:
```java
// Complete Message Validation Implementation
// Java class: com.lenses.schema.MessageValidator

package com.lenses.schema;

import org.apache.avro.Schema;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.io.DecoderFactory;
import software.amazon.awssdk.services.glue.GlueClient;
import software.amazon.awssdk.services.glue.model.*;
import com.google.protobuf.DynamicMessage;
import com.google.protobuf.Descriptors;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.github.fge.jsonschema.main.JsonSchemaFactory;

import java.nio.ByteBuffer;
import java.util.Optional;

public class MessageValidator {

    private final GlueClient glueClient;
    private final String registryName;
    private final SchemaCache schemaCache;
    private final ObjectMapper objectMapper;

    public MessageValidator(GlueClient glueClient, String registryName) {
        this.glueClient = glueClient;
        this.registryName = registryName;
        this.schemaCache = new SchemaCache(5 * 60 * 1000); // 5-minute TTL
        this.objectMapper = new ObjectMapper();
    }

    /**
     * Validate Kafka message against schema from Glue Schema Registry
     * @param messagePayload Raw message bytes
     * @param messageHeaders Kafka message headers (contains schema ID)
     * @return Validation result with success/failure and error details
     */
    public ValidationResult validateMessage(byte[] messagePayload,
                                           Map<String, byte[]> messageHeaders) {
        try {
            // Step 1: Extract schema ID from message headers
            Optional<String> schemaVersionId = extractSchemaVersionId(messageHeaders);

            if (!schemaVersionId.isPresent()) {
                return ValidationResult.failure("No schema version ID found in message headers");
            }

            // Step 2: Fetch schema from Glue (with caching)
            SchemaVersionMetadata schema = getSchemaVersion(schemaVersionId.get());

            if (schema == null) {
                return ValidationResult.failure(
                    "Schema not found in Glue Schema Registry: " + schemaVersionId.get()
                );
            }

            // Step 3: Validate message based on schema format (Avro, JSON, Protobuf)
            switch (schema.getDataFormat()) {
                case "AVRO":
                    return validateAvroMessage(messagePayload, schema);
                case "JSON":
                    return validateJsonMessage(messagePayload, schema);
                case "PROTOBUF":
                    return validateProtobufMessage(messagePayload, schema);
                default:
                    return ValidationResult.failure(
                        "Unsupported schema format: " + schema.getDataFormat()
                    );
            }

        } catch (Exception e) {
            return ValidationResult.failure(
                "Validation error: " + e.getMessage()
            );
        }
    }

    /**
     * Extract schema version ID from Kafka message headers
     * Glue Schema Registry client embeds schema ID in message headers
     */
    private Optional<String> extractSchemaVersionId(Map<String, byte[]> headers) {
        // Glue Schema Registry uses header key: "glue.schemaVersionId"
        byte[] schemaIdBytes = headers.get("glue.schemaVersionId");

        if (schemaIdBytes != null) {
            return Optional.of(new String(schemaIdBytes));
        }

        // Fallback: Check for schema ID embedded in message payload (first 17 bytes)
        // Glue wire format: [HeaderVersion(1)] + [CompressionByte(1)] + [SchemaVersionId(16)]
        return Optional.empty();
    }

    /**
     * Fetch schema version from Glue Schema Registry (with caching)
     */
    private SchemaVersionMetadata getSchemaVersion(String schemaVersionId) {
        // Check cache first
        SchemaVersionMetadata cached = schemaCache.get(schemaVersionId);
        if (cached != null) {
            return cached;
        }

        // Fetch from Glue
        try {
            GetSchemaVersionResponse response = glueClient.getSchemaVersion(
                GetSchemaVersionRequest.builder()
                    .schemaVersionId(schemaVersionId)
                    .build()
            );

            SchemaVersionMetadata metadata = SchemaVersionMetadata.builder()
                .schemaVersionId(schemaVersionId)
                .schemaDefinition(response.schemaDefinition())
                .dataFormat(response.dataFormat())
                .schemaArn(response.schemaArn())
                .build();

            // Cache for 5 minutes
            schemaCache.put(schemaVersionId, metadata);

            return metadata;

        } catch (EntityNotFoundException e) {
            return null;
        }
    }

    /**
     * Validate Avro message against Avro schema
     */
    private ValidationResult validateAvroMessage(byte[] payload, SchemaVersionMetadata schema) {
        try {
            // Parse Avro schema
            Schema.Parser parser = new Schema.Parser();
            Schema avroSchema = parser.parse(schema.getSchemaDefinition());

            // Deserialize message
            GenericDatumReader<GenericRecord> reader = new GenericDatumReader<>(avroSchema);
            var decoder = DecoderFactory.get().binaryDecoder(payload, null);
            GenericRecord record = reader.read(null, decoder);

            if (record == null) {
                return ValidationResult.failure("Failed to deserialize Avro message");
            }

            return ValidationResult.success("Avro message validated successfully");

        } catch (Exception e) {
            return ValidationResult.failure(
                "Avro validation error: " + e.getMessage()
            );
        }
    }

    /**
     * Validate JSON message against JSON Schema
     */
    private ValidationResult validateJsonMessage(byte[] payload, SchemaVersionMetadata schema) {
        try {
            // Parse JSON payload
            JsonNode messageJson = objectMapper.readTree(payload);

            // Parse JSON Schema
            JsonNode schemaJson = objectMapper.readTree(schema.getSchemaDefinition());

            // Validate using JSON Schema validator
            var schemaValidator = JsonSchemaFactory.byDefault()
                .getJsonSchema(schemaJson);

            var report = schemaValidator.validate(messageJson);

            if (report.isSuccess()) {
                return ValidationResult.success("JSON message validated successfully");
            } else {
                return ValidationResult.failure(
                    "JSON validation errors: " + report.toString()
                );
            }

        } catch (Exception e) {
            return ValidationResult.failure(
                "JSON validation error: " + e.getMessage()
            );
        }
    }

    /**
     * Validate Protobuf message against Protobuf schema
     */
    private ValidationResult validateProtobufMessage(byte[] payload,
                                                    SchemaVersionMetadata schema) {
        try {
            // Parse Protobuf schema (.proto file)
            Descriptors.Descriptor descriptor = parseProtobufSchema(
                schema.getSchemaDefinition()
            );

            // Deserialize message
            DynamicMessage message = DynamicMessage.parseFrom(descriptor, payload);

            if (message == null) {
                return ValidationResult.failure("Failed to deserialize Protobuf message");
            }

            // Validate required fields
            for (Descriptors.FieldDescriptor field : descriptor.getFields()) {
                if (field.isRequired() && !message.hasField(field)) {
                    return ValidationResult.failure(
                        "Required field missing: " + field.getName()
                    );
                }
            }

            return ValidationResult.success("Protobuf message validated successfully");

        } catch (Exception e) {
            return ValidationResult.failure(
                "Protobuf validation error: " + e.getMessage()
            );
        }
    }

    private Descriptors.Descriptor parseProtobufSchema(String schemaDefinition) {
        // Implementation: Parse .proto file and build descriptor
        // This would use protobuf-java-util or similar library
        throw new UnsupportedOperationException("Protobuf parsing not yet implemented");
    }
}

/**
 * Validation result wrapper
 */
@Data
@Builder
public class ValidationResult {
    private final boolean success;
    private final String message;
    private final String errorDetails;

    public static ValidationResult success(String message) {
        return ValidationResult.builder()
            .success(true)
            .message(message)
            .build();
    }

    public static ValidationResult failure(String errorDetails) {
        return ValidationResult.builder()
            .success(false)
            .message("Validation failed")
            .errorDetails(errorDetails)
            .build();
    }
}

/**
 * Schema cache with TTL
 */
class SchemaCache {
    private final Map<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final long ttlMillis;

    SchemaCache(long ttlMillis) {
        this.ttlMillis = ttlMillis;
    }

    SchemaVersionMetadata get(String schemaVersionId) {
        CacheEntry entry = cache.get(schemaVersionId);
        if (entry != null && !entry.isExpired()) {
            return entry.getSchema();
        }
        return null;
    }

    void put(String schemaVersionId, SchemaVersionMetadata schema) {
        cache.put(schemaVersionId, new CacheEntry(schema, System.currentTimeMillis() + ttlMillis));
    }

    @Data
    static class CacheEntry {
        private final SchemaVersionMetadata schema;
        private final long expirationTime;

        boolean isExpired() {
            return System.currentTimeMillis() > expirationTime;
        }
    }
}
