#### REQ-LENS-011-006: Schema Diff Visualization

**Status**: Mandatory (Phase 2)
**Rationale**: Understand schema changes between versions

**Diff Features**:
- Side-by-side comparison of versions (v1 vs v2)
- Highlight added fields (green)
- Highlight removed fields (red)
- Highlight modified field types (yellow)
- Show compatibility impact (breaking vs non-breaking change)

**Implementation**:
```javascript
// Complete Schema Diff Visualization Implementation
// JavaScript module: schema-diff-visualizer.js

class SchemaDiffVisualizer {
    /**
     * Calculate and visualize differences between two schema versions
     * Detects breaking vs non-breaking changes
     */

    constructor(containerId) {
        this.container = document.getElementById(containerId);
    }

    calculateDiff(oldSchema, newSchema) {
        /**
         * Calculate diff between schema versions
         * Returns: { changes: Array, breakingChanges: Array }
         */

        const changes = [];
        const breakingChanges = [];

        // Parse schemas (assuming Avro format)
        const oldFields = this.parseAvroSchema(oldSchema);
        const newFields = this.parseAvroSchema(newSchema);

        // Detect added fields
        for (const fieldName in newFields) {
            if (!(fieldName in oldFields)) {
                const field = newFields[fieldName];
                const change = {
                    type: 'added',
                    fieldName: fieldName,
                    fieldType: field.type,
                    isBreaking: !field.hasDefault && field.required
                };

                changes.push(change);

                if (change.isBreaking) {
                    breakingChanges.push({
                        ...change,
                        reason: "Required field added without default value (breaks BACKWARD compatibility)"
                    });
                }
            }
        }

        // Detect removed fields
        for (const fieldName in oldFields) {
            if (!(fieldName in newFields)) {
                const change = {
                    type: 'removed',
                    fieldName: fieldName,
                    fieldType: oldFields[fieldName].type,
                    isBreaking: true  // Removing fields always breaks FORWARD compatibility
                };

                changes.push(change);
                breakingChanges.push({
                    ...change,
                    reason: "Field removed (breaks FORWARD compatibility)"
                });
            }
        }

        // Detect modified fields
        for (const fieldName in oldFields) {
            if (fieldName in newFields) {
                const oldField = oldFields[fieldName];
                const newField = newFields[fieldName];

                if (oldField.type !== newField.type) {
                    const change = {
                        type: 'modified',
                        fieldName: fieldName,
                        oldType: oldField.type,
                        newType: newField.type,
                        isBreaking: true  // Type changes are usually breaking
                    };

                    changes.push(change);
                    breakingChanges.push({
                        ...change,
                        reason: "Field type changed (breaks compatibility)"
                    });
                }
            }
        }

        return { changes, breakingChanges };
    }

    parseAvroSchema(schemaJson) {
        /**
         * Parse Avro schema into field map
         */

        const schema = JSON.parse(schemaJson);
        const fields = {};

        if (schema.fields) {
            schema.fields.forEach(field => {
                fields[field.name] = {
                    type: field.type,
                    hasDefault: 'default' in field,
                    required: !('default' in field),
                    doc: field.doc || ''
                };
            });
        }

        return fields;
    }

    renderDiff(oldSchema, newSchema, oldVersion, newVersion) {
        /**
         * Render side-by-side diff visualization with syntax highlighting
         */

        const { changes, breakingChanges } = this.calculateDiff(oldSchema, newSchema);

        // Create HTML structure
        const html = `
            <div class="schema-diff-container">
                <div class="schema-diff-header">
                    <h3>Schema Diff: v${oldVersion} → v${newVersion}</h3>
                    ${breakingChanges.length > 0 ?
                        `<span class="breaking-changes-badge">⚠️ ${breakingChanges.length} Breaking Changes</span>` :
                        `<span class="safe-changes-badge">✓ Non-Breaking Changes</span>`
                    }
                </div>

                <div class="schema-diff-content">
                    <div class="schema-diff-side">
                        <h4>v${oldVersion} (Previous)</h4>
                        <pre class="schema-code">${this.highlightSchema(oldSchema, changes, 'old')}</pre>
                    </div>

                    <div class="schema-diff-side">
                        <h4>v${newVersion} (New)</h4>
                        <pre class="schema-code">${this.highlightSchema(newSchema, changes, 'new')}</pre>
                    </div>
                </div>

                <div class="changes-summary">
                    <h4>Change Summary</h4>
                    ${this.renderChangesSummary(changes, breakingChanges)}
                </div>
            </div>
        `;

        this.container.innerHTML = html;
    }

    highlightSchema(schemaJson, changes, version) {
        /**
         * Apply color-coding to schema based on changes
         * Green: Added fields, Red: Removed fields, Yellow: Modified fields
         */

        let highlightedSchema = schemaJson;

        changes.forEach(change => {
            if (change.type === 'added' && version === 'new') {
                highlightedSchema = highlightedSchema.replace(
                    new RegExp(`"${change.fieldName}"`, 'g'),
                    `<span class="field-added">"${change.fieldName}"</span>`
                );
            } else if (change.type === 'removed' && version === 'old') {
                highlightedSchema = highlightedSchema.replace(
                    new RegExp(`"${change.fieldName}"`, 'g'),
                    `<span class="field-removed">"${change.fieldName}"</span>`
                );
            } else if (change.type === 'modified') {
                highlightedSchema = highlightedSchema.replace(
                    new RegExp(`"${change.fieldName}"`, 'g'),
                    `<span class="field-modified">"${change.fieldName}"</span>`
                );
            }
        });

        return highlightedSchema;
    }

    renderChangesSummary(changes, breakingChanges) {
        /**
         * Render summary of changes with breaking change warnings
         */

        let html = '<ul class="changes-list">';

        changes.forEach(change => {
            const icon = change.isBreaking ? '⚠️' : '✓';
            const cssClass = change.isBreaking ? 'breaking' : 'safe';

            html += `
                <li class="change-item ${cssClass}">
                    ${icon} ${this.formatChangeDescription(change)}
                </li>
            `;
        });

        html += '</ul>';

        // Add breaking changes alert
        if (breakingChanges.length > 0) {
            html += `
                <div class="breaking-changes-alert">
                    <h5>⚠️ Breaking Changes Detected</h5>
                    <ul>
                        ${breakingChanges.map(bc => `<li>${bc.reason}</li>`).join('')}
                    </ul>
                    <p><strong>Recommendation:</strong> Review compatibility mode and migration plan before deployment.</p>
                </div>
            `;
        }

        return html;
    }

    formatChangeDescription(change) {
        switch (change.type) {
            case 'added':
                return `Added field: <code>${change.fieldName}</code> (${change.fieldType})`;
            case 'removed':
                return `Removed field: <code>${change.fieldName}</code> (${change.fieldType})`;
            case 'modified':
                return `Modified field: <code>${change.fieldName}</code> (${change.oldType} → ${change.newType})`;
            default:
                return 'Unknown change';
        }
    }
}

// CSS Styling
const styles = `
<style>
.schema-diff-container {
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 20px;
}

.breaking-changes-badge {
    background-color: #ff4444;
    color: white;
    padding: 4px 12px;
    border-radius: 12px;
    font-weight: bold;
}

.safe-changes-badge {
    background-color: #44ff44;
    color: #333;
    padding: 4px 12px;
    border-radius: 12px;
    font-weight: bold;
}

.schema-diff-content {
    display: flex;
    gap: 20px;
    margin-top: 20px;
}

.schema-diff-side {
    flex: 1;
}

.field-added { background-color: #d4edda; color: #155724; }
.field-removed { background-color: #f8d7da; color: #721c24; }
.field-modified { background-color: #fff3cd; color: #856404; }

.change-item.breaking { color: #dc3545; }
.change-item.safe { color: #28a745; }

.breaking-changes-alert {
    background-color: #fff3cd;
    border: 2px solid #ffc107;
    padding: 15px;
    margin-top: 20px;
    border-radius: 4px;
}
</style>
`;
```
